function f_myFirstBehaviour() runs on MyComponentType { … }
   function f_mySecondBehaviour() runs on MyComponentType { … }
   function f_myThirdBehaviour(out integer p_p1, inout integer p_p2) 
   runs on MyComponentType 
   return integer { … }
   altstep a_myFourthBehaviour() runs on MyComponentType { ... }
  :
  var MyComponentType v_myNewPTC;
  var MyComponentType v_myAlivePTC;
  var integer v_out, v_inout := 0, v_result;
  :
  v_myNewPTC := MyComponentType.create; // Creation of a new non-alive test component.
  v_myAlivePTC := MyComponentType.create alive; // Creation of a new alive-type test component
  :
  v_myNewPTC.call(f_myFirstBehaviour());  // Call to the non-alive component.
  v_myNewPTC.call(f_mySecondBehaviour());  // Test case error
  :
  v_myAlivePTC.call(f_myFirstBehaviour()); // Call to the alive-type component
  v_myAlivePTC.call(f_mySecondBehaviour()); // Another call to the same component
  :
  v_myAlivePTC.call(f_myThirdBehaviour(v_out,v_inout)) // v_out/v_inout can be changed
   -> value v_result verdict v_verdict; // v_result/v_verdict are assigned on successful
                     // termination
  v_myAlivePTC.call(a_myFourthBehaviour()); // Direct call of an altstep behaviour

